app.get('/api/platform-invoices/reconcile', async (req, res) => {
  const month = String(req.query.month || '');
  if (!/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'month=YYYY-MM required' });
  try {
    const rows = await piLoadVaultRows(month);
    const bks = await piLoadDbBookings();
    const apts = await piLoadDbApts();
    const recon = reconcileBookingMonth(month, bks, apts, rows);
    res.json({
      ok: true,
      month: month,
      bookMonth: recon.bookMonth || '',
      match: !!recon.ok,
      included: (recon.included || []).length,
      expected: (recon.expect && recon.expect.docs) || 0,
      errors: recon.errors || []
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});
